    public function rows(string $type): array
    {
        $queries = self::queries();
        if (!isset($queries[$type])) throw new \RuntimeException('Report type is not supported.', 404);
        return $this->pdo->query($queries[$type])->fetchAll();
    }

    public function refreshMonthlyBalances(): void
    {
        $month = date('Y-m-01');
        $statement = $this->pdo->prepare("INSERT INTO customer_monthly_balances (customer_id,month_start,opening_balance,invoice_amount,payment_amount,credit_amount,closing_balance,generated_at) SELECT c.id,?,COALESCE((SELECT SUM(i.total_amount) FROM invoices i WHERE i.customer_id=c.id AND i.status<>'cancelled' AND i.invoice_date<?),0)-COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.customer_id=c.id AND p.status='cleared' AND p.payment_date<?),0)-COALESCE((SELECT SUM(sr.credit_amount) FROM sales_returns sr WHERE sr.customer_id=c.id AND sr.status IN ('credited','closed') AND sr.return_date<?),0),COALESCE((SELECT SUM(i.total_amount) FROM invoices i WHERE i.customer_id=c.id AND i.status<>'cancelled' AND i.invoice_date>=? AND i.invoice_date<? + INTERVAL 1 MONTH),0),COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.customer_id=c.id AND p.status='cleared' AND p.payment_date>=? AND p.payment_date<? + INTERVAL 1 MONTH),0),COALESCE((SELECT SUM(sr.credit_amount) FROM sales_returns sr WHERE sr.customer_id=c.id AND sr.status IN ('credited','closed') AND sr.return_date>=? AND sr.return_date<? + INTERVAL 1 MONTH),0),0,NOW() FROM customers c ON DUPLICATE KEY UPDATE opening_balance=VALUES(opening_balance),invoice_amount=VALUES(invoice_amount),payment_amount=VALUES(payment_amount),credit_amount=VALUES(credit_amount),closing_balance=VALUES(opening_balance)+VALUES(invoice_amount)-VALUES(payment_amount)-VALUES(credit_amount),generated_at=NOW()");
        $statement->execute([$month,$month,$month,$month,$month,$month,$month,$month,$month,$month]);
        $this->pdo->prepare('UPDATE customer_monthly_balances SET closing_balance=opening_balance+invoice_amount-payment_amount-credit_amount WHERE month_start=?')->execute([$month]);
    }

    public function generateDue(): int
    {
        $generated = 0;
        foreach ($this->pdo->query("SELECT * FROM report_schedules WHERE status='active' AND next_run_at<=NOW() ORDER BY next_run_at FOR UPDATE")->fetchAll() as $schedule) {
            $this->pdo->prepare("INSERT INTO report_runs (report_schedule_id,started_at,status) VALUES (?,NOW(),'running')")->execute([$schedule['id']]);
            $runId = (int) $this->pdo->lastInsertId();
            try {
                $rows = $this->rows((string) $schedule['report_type']);
                $directory = BASE_PATH . '/storage/reports/' . date('Y/m');
                if (!is_dir($directory) && !mkdir($directory,0750,true) && !is_dir($directory)) throw new \RuntimeException('Unable to create report storage.');
                $filename = preg_replace('/[^A-Za-z0-9_-]/','_',strtolower((string)$schedule['schedule_number'])) . '-' . date('Ymd-His') . '.csv';
                $absolute = $directory . '/' . $filename;
                $handle = fopen($absolute,'wb');
                if (!$handle) throw new \RuntimeException('Unable to create scheduled report file.');
                fwrite($handle,"\xEF\xBB\xBF");
                if ($rows) {
                    fputcsv($handle,array_keys($rows[0]));
                    foreach ($rows as $row) fputcsv($handle,$row);
                }
                fclose($handle); @chmod($absolute,0640);
                $relative = str_replace('\\','/',substr($absolute,strlen(BASE_PATH)+1));
                $this->pdo->prepare("UPDATE report_runs SET completed_at=NOW(),row_count=?,file_path=?,status='completed' WHERE id=?")->execute([count($rows),$relative,$runId]);
                $interval = match($schedule['frequency']) {'daily'=>'+1 day','weekly'=>'+1 week','monthly'=>'+1 month'};
                $next = date('Y-m-d H:i:s',strtotime($interval,strtotime((string)$schedule['next_run_at'])));
                while (strtotime($next) <= time()) $next = date('Y-m-d H:i:s',strtotime($interval,strtotime($next)));
                $this->pdo->prepare('UPDATE report_schedules SET next_run_at=? WHERE id=?')->execute([$next,$schedule['id']]);
                $generated++;
            } catch (Throwable $exception) {
                $this->pdo->prepare("UPDATE report_runs SET completed_at=NOW(),status='failed',error_message=? WHERE id=?")->execute([mb_substr($exception->getMessage(),0,1000),$runId]);
                $this->pdo->prepare('UPDATE report_schedules SET next_run_at=DATE_ADD(NOW(),INTERVAL 15 MINUTE) WHERE id=?')->execute([$schedule['id']]);
            }
        }
        return $generated;
    }
